type Extent struct {
	Width  float32
	Height float32
}

// MarshalBinary returns the 8 bytes of an [Extent]: its scalars, little-endian,
// one after another. It never fails.
func (s Extent) MarshalBinary() ([]byte, error) {
	bytes := make([]byte, 8)
	s.put(bytes)
	return bytes, nil
}

// AppendBinary appends the 8 bytes of an [Extent] to bytes, as
// [Extent.MarshalBinary] writes them, and returns the extended bytes. It never
// fails.
func (s Extent) AppendBinary(bytes []byte) ([]byte, error) {
	start := len(bytes)
	bytes = append(bytes, make([]byte, 8)...)
	s.put(bytes[start:])
	return bytes, nil
}

// UnmarshalBinary reads an [Extent] from the start of bytes. It fails with a
// [*tafla.DecodeError] if bytes are shorter than 8.
func (s *Extent) UnmarshalBinary(bytes []byte) error {
	if len(bytes) < 8 {
		return &tafla.DecodeError{Kind: tafla.OutOfRange, ByteLength: 8, Available: len(bytes)}
	}

	*s = readExtent(bytes)
	return nil
}

// ReadExtent reads an [Extent] from the start of bytes and returns it, which
// the compiler can keep in registers, where [Extent.UnmarshalBinary] reads into
// a struct in memory. It fails with a [*tafla.DecodeError] if bytes are shorter
// than 8.
func ReadExtent(bytes []byte) (Extent, error) {
	if len(bytes) < 8 {
		return Extent{}, &tafla.DecodeError{Kind: tafla.OutOfRange, ByteLength: 8, Available: len(bytes)}
	}

	return readExtent(bytes), nil
}

// readExtent reads the scalars of an [Extent] from the start of bytes, which
// hold at least its 8 bytes
func readExtent(bytes []byte) Extent {
	_ = bytes[7]
	var s Extent
	s.Width = math.Float32frombits(binary.LittleEndian.Uint32(bytes))
	s.Height = math.Float32frombits(binary.LittleEndian.Uint32(bytes[4:]))
	return s
}

// put writes the scalars of an [Extent] into the start of bytes, which hold at
// least its 8 bytes
func (s *Extent) put(bytes []byte) {
	_ = bytes[7]
	binary.LittleEndian.PutUint32(bytes, math.Float32bits(s.Width))
	binary.LittleEndian.PutUint32(bytes[4:], math.Float32bits(s.Height))
}

// A message without a version, whose second revision appends `count`
type Sample struct {
	bytes []byte
}

// NewSample reads a [Sample] from bytes, which it keeps rather than copying
// them.
func NewSample(bytes []byte) Sample {
	return Sample{bytes: bytes}
}

// layout returns the layout of a [Sample], which its getters read it in
func (Sample) layout() tafla.TableLayout {
	return tafla.TableLayout{}
}

// Key fails with a [*tafla.DecodeError] if the field lies outside the bytes.
func (t Sample) Key() (uint32, error) {
	reader := tafla.NewTableReader(t.bytes, t.layout())
	position, err := tafla.Uint32FieldOffset(t.bytes, 0, 0)
	if err != nil {
		return 0, err
	}
	return reader.GetUint32(position)
}

// Count returns 7 when the table doesn't hold it, as [Sample.HasCount] tells.
// It fails with a [*tafla.DecodeError] if the field lies outside the bytes.
func (t Sample) Count() (uint16, error) {
	reader := tafla.NewTableReader(t.bytes, t.layout())
	first, err := tafla.Uint32FieldOffset(t.bytes, 0, 0)
	if err != nil {
		return 0, err
	}
	if first < 8 {
		return 7, nil
	}

	position, err := tafla.Uint32FieldOffset(t.bytes, 0, 4)
	if err != nil {
		return 0, err
	}
	if position == 0 {
		return 7, nil
	}

	return reader.GetUint16(position)
}

// HasCount returns whether the table holds [Sample.Count]. It fails with a
// [*tafla.DecodeError] if the field's offset lies outside the bytes.
func (t Sample) HasCount() (bool, error) {
	first, err := tafla.Uint32FieldOffset(t.bytes, 0, 0)
	if err != nil {
		return false, err
	}
	if first < 8 {
		return false, nil
	}

	position, err := tafla.Uint32FieldOffset(t.bytes, 0, 4)
	if err != nil {
		return false, err
	}
	return position != 0, nil
}

// SampleFields are the fields of a [Sample], to write.
type SampleFields struct {
	Key   uint32
	Count uint16
}

// MarshalBinary writes a [Sample] with every field. It fails with a
// [*tafla.BuildError] if it's longer than its offset type, uint32, addresses.
func (f SampleFields) MarshalBinary() ([]byte, error) {
	return f.AppendBinary(nil)
}

// AppendBinary appends a [Sample] with every field to bytes, as
// [SampleFields.MarshalBinary] writes it, and returns the extended bytes, into
// their capacity when they have room. It fails as MarshalBinary does.
func (f SampleFields) AppendBinary(bytes []byte) ([]byte, error) {
	bytes, table, err := tafla.AppendTable(bytes, 2, Sample{}.layout(), 14)
	if err != nil {
		return nil, err
	}

	_ = table[13]
	binary.LittleEndian.PutUint32(table, 8)
	binary.LittleEndian.PutUint32(table[4:], 12)
	binary.LittleEndian.PutUint32(table[8:], f.Key)
	binary.LittleEndian.PutUint16(table[12:], f.Count)

	return bytes, nil
}

